CREATE TABLE IF NOT EXISTS sd_policies(country_code TEXT NOT NULL,priority TEXT NOT NULL,response_minutes INTEGER NOT NULL CHECK(response_minutes BETWEEN 1 AND 43200),resolution_minutes INTEGER NOT NULL CHECK(resolution_minutes BETWEEN 1 AND 525600),pause_on_hold INTEGER NOT NULL DEFAULT 0 CHECK(pause_on_hold IN (0,1)),revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(country_code,priority));
INSERT OR IGNORE INTO sd_policies(country_code,priority,response_minutes,resolution_minutes) SELECT c.code,p.priority,p.response,p.resolution FROM countries c CROSS JOIN (SELECT 'critical' priority,15 response,240 resolution UNION ALL SELECT 'high',60,480 UNION ALL SELECT 'medium',240,1440 UNION ALL SELECT 'low',480,4320) p WHERE c.code IN ('MU','MG','RW','BI');
CREATE TABLE IF NOT EXISTS kb_articles(id TEXT PRIMARY KEY,country_code TEXT NOT NULL,reference TEXT NOT NULL UNIQUE COLLATE NOCASE,title TEXT NOT NULL,category TEXT NOT NULL,service TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','in_review','published','retired')),data TEXT NOT NULL,author_id TEXT NOT NULL REFERENCES users(id),last_editor_id TEXT REFERENCES users(id),reviewer_id TEXT REFERENCES users(id),published_version INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS kb_versions(article_id TEXT NOT NULL REFERENCES kb_articles(id),version INTEGER NOT NULL,title TEXT NOT NULL,data TEXT NOT NULL,author_id TEXT NOT NULL REFERENCES users(id),reviewer_id TEXT NOT NULL REFERENCES users(id),review_note TEXT NOT NULL,published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(article_id,version));
CREATE TABLE IF NOT EXISTS sd_profiles(ticket_id TEXT PRIMARY KEY REFERENCES service_tickets(id),reference TEXT NOT NULL UNIQUE COLLATE NOCASE,ticket_type TEXT NOT NULL CHECK(ticket_type IN ('incident','service_request','project_task','problem','change')),impact INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 3),urgency INTEGER NOT NULL CHECK(urgency BETWEEN 1 AND 3),data TEXT NOT NULL DEFAULT '{}',policy TEXT NOT NULL,activated_at TEXT NOT NULL,held_at TEXT,paused_seconds INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,closed_at TEXT,reopen_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sd_task_tickets(task_id TEXT PRIMARY KEY REFERENCES work_tasks(id),ticket_id TEXT NOT NULL UNIQUE REFERENCES service_tickets(id),project_id TEXT NOT NULL REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS sd_events(id TEXT PRIMARY KEY,ticket_id TEXT REFERENCES service_tickets(id),article_id TEXT REFERENCES kb_articles(id),country_code TEXT NOT NULL,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sd_kb_usage(ticket_id TEXT NOT NULL REFERENCES service_tickets(id),article_id TEXT NOT NULL,version INTEGER NOT NULL,usage_note TEXT NOT NULL,used_by TEXT NOT NULL REFERENCES users(id),used_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,closure_cycle INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(ticket_id,article_id,version),FOREIGN KEY(article_id,version) REFERENCES kb_versions(article_id,version));
CREATE TABLE IF NOT EXISTS sd_alerts(id TEXT PRIMARY KEY,ticket_id TEXT REFERENCES service_tickets(id),article_id TEXT REFERENCES kb_articles(id),country_code TEXT NOT NULL,rule TEXT NOT NULL,entity_key TEXT NOT NULL,message TEXT NOT NULL,severity TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',acknowledged_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(rule,entity_key));
CREATE TABLE IF NOT EXISTS sd_notifications(alert_id TEXT NOT NULL REFERENCES sd_alerts(id),user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'available',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(alert_id,user_id));
CREATE TABLE IF NOT EXISTS sd_approvals(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES service_tickets(id),requested_by TEXT NOT NULL REFERENCES users(id),approver_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending',note TEXT NOT NULL,decision_note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS sd_one_approval ON sd_approvals(ticket_id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS sd_guards(ticket_id TEXT PRIMARY KEY,revision INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS sd_revision_guard BEFORE INSERT ON sd_guards WHEN NOT EXISTS(SELECT 1 FROM sd_profiles WHERE ticket_id=NEW.ticket_id AND revision=NEW.revision) BEGIN SELECT RAISE(ABORT,'SD revision conflict'); END;
CREATE TABLE IF NOT EXISTS kb_guards(article_id TEXT PRIMARY KEY,revision INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS kb_revision_guard BEFORE INSERT ON kb_guards WHEN NOT EXISTS(SELECT 1 FROM kb_articles WHERE id=NEW.article_id AND revision=NEW.revision) BEGIN SELECT RAISE(ABORT,'KB revision conflict'); END;
CREATE TABLE IF NOT EXISTS sd_scan_runs(id TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'running',evaluated INTEGER NOT NULL DEFAULT 0,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,error TEXT);
CREATE INDEX IF NOT EXISTS sd_event_ticket ON sd_events(ticket_id,created_at);
CREATE INDEX IF NOT EXISTS sd_queue_status ON service_tickets(status,assigned_to);
CREATE TRIGGER IF NOT EXISTS kb_version_immutable BEFORE UPDATE ON kb_versions BEGIN SELECT RAISE(ABORT,'Published knowledge version is immutable'); END;
CREATE TRIGGER IF NOT EXISTS sd_close_kb_guard BEFORE UPDATE OF status ON service_tickets WHEN NEW.status='closed' AND OLD.status<>'closed' AND EXISTS(SELECT 1 FROM sd_profiles WHERE ticket_id=NEW.id) AND NOT EXISTS(SELECT 1 FROM sd_kb_usage k JOIN sd_profiles p ON p.ticket_id=k.ticket_id WHERE k.ticket_id=NEW.id AND k.closure_cycle=p.reopen_count) BEGIN SELECT RAISE(ABORT,'Knowledge reference required before closure'); END;
CREATE TRIGGER IF NOT EXISTS sd_task_completion_guard BEFORE UPDATE OF status ON work_tasks WHEN NEW.status='done' AND EXISTS(SELECT 1 FROM sd_task_tickets l JOIN service_tickets t ON t.id=l.ticket_id WHERE l.task_id=NEW.id AND t.status<>'closed') BEGIN SELECT RAISE(ABORT,'Close linked service ticket to complete this task'); END;
CREATE TRIGGER IF NOT EXISTS sd_ticket_task_close AFTER UPDATE OF status ON service_tickets WHEN NEW.status='closed' AND OLD.status<>'closed' AND EXISTS(SELECT 1 FROM sd_task_tickets WHERE ticket_id=NEW.id) BEGIN UPDATE work_tasks SET status='done',completed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=(SELECT task_id FROM sd_task_tickets WHERE ticket_id=NEW.id); INSERT INTO pm_audit(id,project_id,action,snapshot) SELECT lower(hex(randomblob(16))),project_id,'Service ticket closed; project task completed',json_object('ticket_id',NEW.id,'task_id',task_id) FROM sd_task_tickets WHERE ticket_id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS sd_ticket_task_reopen AFTER UPDATE OF status ON service_tickets WHEN OLD.status='closed' AND NEW.status<>'closed' AND EXISTS(SELECT 1 FROM sd_task_tickets WHERE ticket_id=NEW.id) BEGIN UPDATE work_tasks SET status='todo',completed_at=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=(SELECT task_id FROM sd_task_tickets WHERE ticket_id=NEW.id); INSERT INTO pm_audit(id,project_id,action,snapshot) SELECT lower(hex(randomblob(16))),project_id,'Service ticket reopened; task reopened',json_object('ticket_id',NEW.id,'task_id',task_id) FROM sd_task_tickets WHERE ticket_id=NEW.id; END;
CREATE TABLE IF NOT EXISTS sd_routing(id TEXT PRIMARY KEY,country_code TEXT NOT NULL,category TEXT NOT NULL DEFAULT '*',service TEXT NOT NULL DEFAULT '*',priority TEXT NOT NULL DEFAULT '*',owner_id TEXT NOT NULL REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(country_code,category,service,priority));

CREATE TABLE IF NOT EXISTS sd_policy_guards(country_code TEXT NOT NULL,priority TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(country_code,priority));
CREATE TRIGGER IF NOT EXISTS sd_policy_revision_guard BEFORE INSERT ON sd_policy_guards WHEN NOT EXISTS(SELECT 1 FROM sd_policies WHERE country_code=NEW.country_code AND priority=NEW.priority AND revision=NEW.revision) BEGIN SELECT RAISE(ABORT,'SD revision conflict'); END;
